import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function IsNullBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "logic_isnull_block";
  let mExtensionName = "logic_isnull_extension";

  const mIsNullOperatorOptions = [
    ["Has missing values", "IS NULL"],
    ["Has no missing values", "IS NOT NULL"]
  ];

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function registerExtension() {
    // ? Unregister the existing extension
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    // ? Register the new/updated extension
    Blockly.Extensions.register(mExtensionName, function () {
      this.data = {
        CustomID: mBlockID,
        BlockType: "LOGIC",
        IsHeadBlock: false
      };
    });
  }

  function generateSQLCodeForBlock() {
    // ? Generate the JavaScript code for this block
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      let code = "";
      // ? IsNull Operator
      const isnullOperator = block.getFieldValue("ISNULL_OPERATOR");

      // ? get connected block,  // 12Aug2024
      // const previousBlock = block.getPreviousBlock();
      const previousBlock = block.previousConnection.targetBlock();
      // ? Dataset
      const datasetName = previousBlock.getFieldValue("DATASET");
      const dataset = mDatasetList.find(function (d) {
        return d.Name === datasetName;
      });
      // ? Column
      let columnName = previousBlock.getFieldValue("COLUMNS_FIELD");
      const column = dataset.SelColumnsList.find(function (d) {
        return d.ColumnName === columnName;
      });

      // ? WHERE block
      if (previousBlock.type === "logic_where_block") {
        code = ` ${columnName} ${isnullOperator}`;
      }

      // 22Feb2025 return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  function runBlockJsonInit() {
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "%1",
          args0: [
            {
              type: "field_dropdown",
              name: "ISNULL_OPERATOR",
              options: mIsNullOperatorOptions
            }
          ],
          // 20May2024 id: Blockly.utils.genUid(),   // 20May2024
          data: { CustomID: mBlockID, BlockType: "LOGIC", IsHeadBlock: false }, // ? I don't like the structure of the UID that Blockly generates
          extensions: [mExtensionName],
          previousStatement: null,
          nextStatement: null,
          colour: 200,
          tooltip: "tooltip text",
          helpUrl: ""
        });
      },
      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
      }
    };
  }

  function createBlock() {
    runBlockJsonInit();

    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit();

    // ? Re-render the workspace
    Blockly.getMainWorkspace().render();
  };

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mToolsCategory = config.ToolsCategory;
    mDatasetList = config.DatasetList;
    mBlockID = mHelperUtil.generateShortGUID();
    Blockly.setLocale(En);
    registerExtension();
    createBlock();
  };

  return publicAPI;
}
export default IsNullBlock;
