import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function AggregationOrderByBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "aggregation_orderby_block";
  let mExtensionName = "aggregation_orderby_extension";
  const mOrderOperatorOptions = [
    ["A to Z", "ASC"],
    ["Z to A", "DESC"],
    ["Smallest to Largest", "ASC"],
    ["Largest to Smallest", "DESC"]
  ];

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function registerExtension() {
    // ? Unregister the existing extension
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    // ? Register the new/updated extension
    Blockly.Extensions.register(mExtensionName, function () {
      const datasetDropdown = this.getField("DATASET");
      this.data = {
        CustomID: mBlockID,
        BlockType: "AGGREGATION",
        IsHeadBlock: false
      }; // 20May2024

      this.getInput("COLUMNS_INPUT").appendField(
        new Blockly.FieldDropdown(function () {
          const datasetName = datasetDropdown.getValue();
          const options = getColumnsListOptions(datasetName);
          return options;
        }),
        "COLUMNS_FIELD"
      );
    });
  }

  function generateSQLCodeForBlock() {
    // ? Generate the JavaScript code for this block
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      let code = "";

      const orderOperator = block.getFieldValue("ORDER_OPERATOR");

      // ? Dataset
      const datasetName = block.getFieldValue("DATASET");
      const dataset = mDatasetList.find(function (d) {
        return d.Name === datasetName;
      });
      // ? Column
      let columnName = block.getFieldValue("COLUMNS_FIELD");
      const column = dataset.SelColumnsList.find(function (d) {
        return d.ColumnName === columnName;
      });

      code = ` ORDER BY ${columnName} ${orderOperator} `;

      // 22Feb2025 return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  function getColumnsListOptions(newDatasetName) {
    const dataset = mDatasetList.find(function (d) {
      return d.Name === newDatasetName;
    });
    const datasetColumnsOptions = [];
    for (const element of dataset.SelColumnsList) {
      datasetColumnsOptions.push([element.ColumnName, element.ColumnName]);
    }
    return datasetColumnsOptions;
  }

  function getDatasetNamesList() {
    const datasetOptions = [];
    for (const element of mDatasetList) {
      datasetOptions.push([element.Name, element.Name]);
    }

    return datasetOptions;
  }

  function runBlockJsonInit() {
    const datasetOptions = getDatasetNamesList();
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "Arrange %1::%2 %3",
          args0: [
            {
              type: "field_dropdown",
              name: "DATASET",
              options: datasetOptions
            },
            {
              type: "input_dummy",
              name: "COLUMNS_INPUT"
            },
            {
              type: "field_dropdown",
              name: "ORDER_OPERATOR",
              options: mOrderOperatorOptions
            }
          ],
          data: {
            CustomID: mBlockID,
            BlockType: "AGGREGATION",
            IsHeadBlock: false
          }, // ? I don't like the structure of the UID that Blockly generates
          extensions: [mExtensionName],
          previousStatement: null,
          colour: 50,
          tooltip: "tooltip text",
          helpUrl: ""
        });

        // 15Sep2024
        const datasetDropdown = this.getField("DATASET");
        const columnsInput = this.getInput("COLUMNS_INPUT");
        let datasetColumnsList;

        // ? Add a change event listener to the Dataset dropdown field
        datasetDropdown.setValidator(function (newDatasetName) {
          columnsInput.removeField("COLUMNS_FIELD");
          columnsInput.appendField(
            new Blockly.FieldDropdown(function () {
              datasetColumnsList = getColumnsListOptions(newDatasetName);
              return datasetColumnsList;
            }),
            "COLUMNS_FIELD"
          );
        });
      },
      // 15Sep2024
      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
        const datasetOptions = getDatasetNamesList();

        const updateDropdown = (field, options) => {
          const currentValue = field.getValue();
          field.menuGenerator_ = options;

          // Check if the current value exists in the new options
          const valueExists = options.some(
            (option) => option[1] === currentValue
          );

          if (valueExists) {
            // If the current value still exists, keep it
            field.setValue(currentValue);
          } else {
            // If the current value doesn't exist, set to the first option
            field.setValue(options[0][1]);
          }

          field.forceRerender();
        };

        // Update DATASET
        const datasetDDL = this.getField("DATASET");
        updateDropdown(datasetDDL, datasetOptions);
      }
    };
  }

  function createBlock() {
    runBlockJsonInit();

    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit();

    // ? Re-render the workspace
    Blockly.getMainWorkspace().render();
  };

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mToolsCategory = config.ToolsCategory;
    mDatasetList = config.DatasetList;
    mBlockID = mHelperUtil.generateShortGUID();
    Blockly.setLocale(En);
    registerExtension();
    createBlock();
  };

  return publicAPI;
}
export default AggregationOrderByBlock;
