import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function DataCategorizeBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "aggregation_data_categorize_block";
  let mExtensionName = "aggregation_data_categorize_extension";

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function getDatasetNamesList() {
    return mDatasetList.map((dataset) => [dataset.Name, dataset.Name]);
  }

  function getColumnsListOptions(datasetName) {
    const dataset = mDatasetList.find((d) => d.Name === datasetName);
    return dataset.SelColumnsList.map((col) => [
      col.ColumnName,
      col.ColumnName
    ]);
  }

  function registerExtension() {
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    Blockly.Extensions.register(mExtensionName, function () {
      this.data = {
        CustomID: mBlockID,
        BlockType: "AGGREGATION",
        IsHeadBlock: true
      }; // 13Feb2025

      this.getInput("COLUMN_INPUT").appendField(
        new Blockly.FieldDropdown(() => {
          const datasetName = this.getFieldValue("DATASET");
          return getColumnsListOptions(datasetName);
        }),
        "COLUMN"
      );
    });
  }

  function createCategoryInput(block, index) {
    const input = block
      .appendDummyInput(`CATEGORY_${index}`)
      .appendField(`Category ${index + 1}:`)
      .appendField(
        new Blockly.FieldDropdown([
          ["<", "<"],
          ["<=", "<="],
          [">", ">"],
          [">=", ">="],
          ["=", "="]
        ]),
        `OPERATOR_${index}`
      )
      .appendField(new Blockly.FieldNumber(0), `VALUE_${index}`)
      .appendField("Label:")
      .appendField(
        new Blockly.FieldTextInput(`Category ${index + 1}`),
        `LABEL_${index}`
      );
    return input;
  }

  function runBlockJsonInit() {
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "Categorize %1",
          args0: [
            {
              type: "field_dropdown",
              name: "DATASET",
              options: getDatasetNamesList()
            }
          ],
          message1: "Column %1",
          args1: [
            {
              type: "input_dummy",
              name: "COLUMN_INPUT"
            }
          ],
          message2: "Category title: %1",
          args2: [
            {
              type: "field_input",
              name: "CATEGORY_TITLE",
              text: "Category"
            }
          ],
          message3: "Number of categories: %1",
          args3: [
            {
              type: "field_number",
              name: "NUM_CATEGORIES",
              value: 3,
              min: 2,
              max: 10
            }
          ],
          message4: "Define categories:",
          args4: [],
          data: {
            CustomID: mBlockID,
            BlockType: "AGGREGATION",
            IsHeadBlock: true
          },
          extensions: [mExtensionName],
          previousStatement: null,
          nextStatement: null,
          colour: 50,
          tooltip: "Create categories based on value ranges",
          helpUrl: ""
        });

        // Add category inputs
        for (let i = 0; i < 3; i++) {
          createCategoryInput(this, i);
        }

        this.setOnChange(function (changeEvent) {
          if (
            changeEvent.type === "change" &&
            changeEvent.name === "NUM_CATEGORIES"
          ) {
            this.updateCategoryInputs();
          } else if (
            changeEvent.type === "change" &&
            changeEvent.name === "DATASET"
          ) {
            this.updateColumnDropdown();
          }
        });
      },

      updateCategoryInputs: function () {
        const numCategories = parseInt(this.getFieldValue("NUM_CATEGORIES"));
        const currentInputs = this.inputList.filter((input) =>
          input.name.startsWith("CATEGORY_")
        );

        // Remove excess inputs
        while (currentInputs.length > numCategories) {
          this.removeInput(currentInputs.pop().name);
        }

        // Add new inputs
        while (currentInputs.length < numCategories) {
          createCategoryInput(this, currentInputs.length);
          currentInputs.push(this.inputList[this.inputList.length - 1]);
        }
      },

      updateColumnDropdown: function () {
        const datasetName = this.getFieldValue("DATASET");
        const columnOptions = getColumnsListOptions(datasetName);

        // Remove the existing COLUMN field
        this.getInput("COLUMN_INPUT").removeField("COLUMN");

        // Add the new COLUMN field with updated options
        this.getInput("COLUMN_INPUT").appendField(
          new Blockly.FieldDropdown(columnOptions),
          "COLUMN"
        );

        // Set the value to the first item in the new list
        if (columnOptions.length > 0) {
          this.setFieldValue(columnOptions[0][1], "COLUMN");
        }
      },

      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
        const datasetOptions = getDatasetNamesList();
        const datasetField = this.getField("DATASET");
        datasetField.menuGenerator_ = datasetOptions;
        datasetField.setValue(datasetOptions[0][1]);
        this.getInput("COLUMN_INPUT").removeField("COLUMN");
        this.getInput("COLUMN_INPUT").appendField(
          new Blockly.FieldDropdown(() =>
            getColumnsListOptions(datasetOptions[0][1])
          ),
          "COLUMN"
        );
      }
    };
  }

  function generateSQLCodeForBlock() {
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      // 21Feb2025 const tblName = `tblHeadBlock_${mBlockID}`;
      const blockID = block.data.CustomID; // 21Feb2025
      const tblName = `tblHeadBlock_${blockID}`; // 21Feb2025
      const datasetName = this.getFieldValue("DATASET");
      const dataset = mDatasetList.find((d) => d.Name === datasetName);
      const datasetTableName = dataset.TableName;
      const columnName = block.getFieldValue("COLUMN");
      const categoryTitle = block
        .getFieldValue("CATEGORY_TITLE")
        .replace(/\s+/g, "_");  // ? replace whitespace with underscore 
      const numCategories = parseInt(block.getFieldValue("NUM_CATEGORIES"));

      let categoriesCode = [];
      for (let i = 0; i < numCategories; i++) {
        const operator = block.getFieldValue(`OPERATOR_${i}`);
        const value = block.getFieldValue(`VALUE_${i}`);
        const label = block.getFieldValue(`LABEL_${i}`);
        categoriesCode.push(
          `WHEN ${columnName} ${operator} ${value} THEN '${label}'`
        );
      }

      const code = `
         -- Create a copy of the original table
      CREATE OR REPLACE TABLE ${tblName} AS SELECT * FROM ${datasetTableName};

      -- Add the new category column to the copied table
      ALTER TABLE ${tblName}
      ADD COLUMN ${categoryTitle} TEXT;
      
      -- Update the new column in the copied table
      UPDATE ${tblName}
      SET ${categoryTitle} = CASE
        ${categoriesCode.join("\n")}
        ELSE 'Uncategorized'
      END;
      `;

      // 22Feb2025 return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function createBlock() {
    runBlockJsonInit();
    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit();
    Blockly.getMainWorkspace().render();
  };

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mToolsCategory = config.ToolsCategory;
    mDatasetList = config.DatasetList;
    mBlockID = mHelperUtil.generateShortGUID();
    Blockly.setLocale(En);
    registerExtension();
    createBlock();
  };

  return publicAPI;
}

export default DataCategorizeBlock;
