import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function SpatialFindJoinBlock() {
  const publicAPI = {};
  let mMediator;
  let mDatasetList;
  let mBlockID; // 20May2024
  let mHelperUtil;
  let mToolsCategory;
  const mBlockName = "spatial_find_join_block";
  const mExtensionName = "spatial_find_join_extension";

  // 12Jun2024
  const mDatasetOriginTypes = {
    // 02Feb2025 External: "External",
    Remote: "Remote", // 02Feb2025
    Local: "Local", // 02Feb2025
    Block: "Block",
    Workflow: "Workflow",
    WorkflowStep: "WorkflowStep"
  };

  // 24Aug2024
  const mSpatialOperatorOptions = [
    ["contain(s)", "ST_Contains"],
    ["share any common space with (intersect)", "ST_Intersects"],
    ["is/are completely within", "ST_WITHIN"],
    ["are completely covered by", "ST_CoveredBy"],
    ["overlap(s)", "ST_Overlaps"],
    ["touch(es)", "ST_Touches"],
    ["cross(es)", "ST_Crosses"],
    ["completely cover(s)", "ST_Covers"]
  ];

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function getDatasetNamesList() {
    const datasetOptions = [];
    for (let i = 0; i < mDatasetList.length; i += 1) {
      datasetOptions.push([mDatasetList[i].Name, mDatasetList[i].Name]);
    }

    return datasetOptions;
  }

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function registerExtension() {
    // ? Unregister the existing extension
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    // ? Register the new/updated extension
    Blockly.Extensions.register(mExtensionName, function () {
      const datasetOptions = getDatasetNamesList();
      this.data = {
        CustomID: mBlockID,
        BlockType: "SPATIAL",
        IsHeadBlock: true
      }; // 20May2024

      this.getInput("DATASET1").appendField(
        new Blockly.FieldDropdown(function () {
          return datasetOptions;
        }),
        "DATASET1"
      );

      this.getInput("DATASET2").appendField(
        new Blockly.FieldDropdown(function () {
          return datasetOptions;
        }),
        "DATASET2"
      );
    });
  }

  function formatColumnsForSQL(columnsList, alias) {
    // ? Map over the columns array and format each column name
    const formattedColumns = columnsList.map(function (column) {
      // ? Trim any leading/trailing whitespace
      const columnName = column.trim();

      // ? Wrap the column name in square brackets if it contains spaces
      if (columnName.includes(" ")) {
        return `[${columnName}]`;
      } else {
        return columnName;
      }
    });

    let sqlStr = "";
    // ? Iterate over the columns and append them to the query
    for (let i = 0; i < formattedColumns.length; i++) {
      sqlStr += `${alias}.${formattedColumns[i]}`;
      if (i < formattedColumns.length - 1) {
        sqlStr += ", ";
      }
    }

    return sqlStr;
  }

  // 30Aug2024
  function hasBufferGeometryColumn(columnsList) {
    return columnsList.some(function (col) {
      return col.ColumnName.toUpperCase() === "BUFFER_GEOMETRY"; //? contains at least 'BUFFER_GEOMETRY', may also contain 'GEOMETRY'
    });
  }

  // 13Jan2025
  function getGeomColName(columnsList) {
    const geomCol = columnsList.find(function (col) {
      return col.ColumnType.toUpperCase() === "GEOMETRY";
    });
    if (geomCol) {
      return geomCol.ColumnName;
    }
    return "No Geometry Column Found";
  }

  function generateSQLCodeForBlock() {
    // ? Generate the JavaScript code for this block
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      let code = "";
      let hasBufferGeometry; // 30Aug2024

      // ? Dataset 1
      const dataset1Alias = "d1"; // 06Sep2024"
      const dataset1Name = block.getFieldValue("DATASET1");
      const dataset1 = mDatasetList.find(function (d) {
        return d.Name === dataset1Name;
      });
      const dataset1SelColumnsList = dataset1.SelColumnsList.map(function (d) {
        return d.ColumnName;
      });
      // ? get columns list for SQL query
      /*  // 13Jan2025
      const dataset1SQLStr = formatColumnsForSQL(
        dataset1SelColumnsList,
        dataset1Alias
      ); */
      // 13Jan2025
      let dataset1SQLStr;
      if (dataset1.SelColumnsList.length < dataset1.ColumnsList) {
        dataset1SQLStr = formatColumnsForSQL(
          dataset1SelColumnsList,
          dataset1Alias
        );
      } else {
        dataset1SQLStr = `${dataset1Alias}.*`;
      }
      const dataset1GeomColumnName = getGeomColName(dataset1.ColumnsList); // 13Jan2025
      // ? Add the DISTINCT Operator SQL , // 13Jan2025
      const distinctOperator = block.getFieldValue("DISTINCT_OPERATOR");
      if (distinctOperator === "DISTINCT") {
        dataset1SQLStr = `DISTINCT ON(${dataset1Alias}.${dataset1GeomColumnName}) ${dataset1SQLStr}`;
      }

      hasBufferGeometry = hasBufferGeometryColumn(dataset1.ColumnsList); // 30Aug2024
      /*  // 13Jan2025
      const dataset1GeomColumnName = hasBufferGeometry
        ? "buffer_geometry"
        : "geometry"; // 30Aug2024 */

      // ? Spatial Find Operator,
      const spatialFindOperator = block.getFieldValue("SPATIAL_FIND_OPERATOR");

      // ? Dataset 2
      const dataset2Alias = "d2"; // 06Sep2024
      const dataset2Name = block.getFieldValue("DATASET2");
      const dataset2 = mDatasetList.find(function (d) {
        return d.Name === dataset2Name;
      });

      // 02Sep2024
      const dataset2SelColumnsList = dataset2.SelColumnsList.filter(
        function (d) {
          return (
            // 12Jan2025 d.ColumnName !== "geometry" && d.ColumnName !== "buffer_geometry" // ? remove geometry column, 02Sep2024
            d.ColumnType.toUpperCase() !== "GEOMETRY" &&
            d.ColumnName !== "buffer_geometry" //  ? 12Jan2025, remove geometry column, 02Sep2024
          );
        }
      ).map(function (d) {
        return d.ColumnName;
      });

      const dataset2GeomColumnName = getGeomColName(dataset2.ColumnsList); // 13Jan2025
      // ? get columns list for SQL query
      /* // 13Jan2025
      const dataset2SQLStr = formatColumnsForSQL(
        dataset2SelColumnsList,
        dataset2Alias
      ); // 02Sep2024 */
      // 13Jan2025
      let dataset2SQLStr;
      if (dataset2.SelColumnsList.length < dataset2.ColumnsList) {
        dataset2SQLStr = formatColumnsForSQL(
          dataset2SelColumnsList,
          dataset2Alias
        );
      } else {
        dataset2SQLStr = `${dataset2Alias}.* EXCLUDE(${dataset2GeomColumnName})`;
      }

      // 12Feb2025 hasBufferGeometry = hasBufferGeometryColumn(dataset2.ColumnsList); // 30Aug2024
      /*  // 13Jan2025
      const dataset2GeomColumnName = hasBufferGeometry
        ? "buffer_geometry"
        : "geometry"; // 30Aug2024 */

      /*  // 11Feb2025
      // 12Jun2024
      let readDataset1SQL;
      if (dataset1.Origin === mDatasetOriginTypes.Remote) {
        readDataset1SQL = `read_parquet('${dataset1.Url}')`;
      } else if (dataset1.Origin === mDatasetOriginTypes.Block) {
        readDataset1SQL = dataset1.TableName;
      }

      let readDataset2SQL;
      if (dataset2.Origin === mDatasetOriginTypes.Remote) {
        readDataset2SQL = `read_parquet('${dataset2.Url}')`;
      } else if (dataset2.Origin === mDatasetOriginTypes.Block) {
        readDataset2SQL = dataset2.TableName;
      } */

      const readDataset1SQL = dataset1.TableName; // 11Feb2025
      const readDataset2SQL = dataset2.TableName; // 11Feb2025

      /*  // 12Feb2025
      // 15Aug2024
      let dataset1GeomSQL;
      if (dataset1.CRS !== "EPSG:3857") {
        if (dataset1GeomColumnName === "buffer_geometry") {
          // ? buffer_gemetry is created by application after using ST_GeomFromWKB, so we don't need to transform it,  // 30Aug2024
          dataset1GeomSQL = `ST_Transform(${dataset1Alias}.${dataset1GeomColumnName},'${dataset1.CRS}','EPSG:3857')`;
        } else {
          // 26Sep2024 dataset1GeomSQL = `ST_Transform(ST_GeomFromWKB(${dataset1Alias}.${dataset1GeomColumnName}),'${dataset1.CRS}','EPSG:3857')`;
          dataset1GeomSQL = `ST_Transform(${dataset1Alias}.${dataset1GeomColumnName},'${dataset1.CRS}','EPSG:3857')`; // 26Sep2024
        }
      } else if (dataset1.CRS === "EPSG:3857") {
        if (dataset1GeomColumnName === "buffer_geometry") {
          // ? buffer_gemetry is created by application after using ST_GeomFromWKB, so we don't need to transform it,  // 30Aug2024
          dataset1GeomSQL = `${dataset1Alias}.${dataset1GeomColumnName}`;
        } else {
          // 26Sep2024 dataset1GeomSQL = `ST_GeomFromWKB(${dataset1Alias}.${dataset1GeomColumnName})`;
          dataset1GeomSQL = `${dataset1Alias}.${dataset1GeomColumnName}`; // 26Sep2024
        }
      }

      // 15Aug2024
      let dataset2GeomSQL;
      if (dataset2.CRS !== "EPSG:3857") {
        if (dataset2GeomColumnName === "buffer_geometry") {
          // ? buffer_gemetry is created by application after using ST_GeomFromWKB, so we don't need to transform it,  // 30Aug2024
          dataset2GeomSQL = `ST_Transform(${dataset2Alias}.${dataset2GeomColumnName},'${dataset2.CRS}','EPSG:3857')`;
        } else {
          // 26Sep2024 dataset2GeomSQL = `ST_Transform(ST_GeomFromWKB(${dataset2Alias}.${dataset2GeomColumnName}),'${dataset2.CRS}','EPSG:3857')`;
          dataset2GeomSQL = `ST_Transform(${dataset2Alias}.${dataset2GeomColumnName},'${dataset2.CRS}','EPSG:3857')`; // 26Sep2024
        }
      } else if (dataset2.CRS === "EPSG:3857") {
        if (dataset2GeomColumnName === "buffer_geometry") {
          // ? buffer_gemetry is created by application after using ST_GeomFromWKB, so we don't need to transform it, // 30Aug2024
          dataset2GeomSQL = `${dataset2Alias}.${dataset2GeomColumnName}`;
        } else {
          // 26Sep2024 dataset2GeomSQL = `ST_GeomFromWKB(dataset2Alias.${dataset2GeomColumnName})`;
          dataset2GeomSQL = `${dataset2Alias}.${dataset2GeomColumnName}`;
        }
      } */

      const dataset1GeomSQL = `${dataset1Alias}.${dataset1GeomColumnName}`; // 12Feb2025
      const dataset2GeomSQL = `${dataset2Alias}.${dataset2GeomColumnName}`; // 12Feb2025
      // 21Feb2025 const tblName = `tblHeadBlock_${mBlockID}`;
      const blockID = block.data.CustomID; // 21Feb2025
      const tblName = `tblHeadBlock_${blockID}`; // 21Feb2025

      code =
        // 02Sep2024 `Create Or Replace Table ${tblName} As SELECT DISTINCT ${dataset1SQLStr} FROM ` +
        `Create Or Replace Table ${tblName} As SELECT ${dataset1SQLStr}, ${dataset2SQLStr} FROM ` + // 02Sep2024
        readDataset2SQL +
        ` AS d2 JOIN ` +
        readDataset1SQL +
        ` AS d1 ON ${spatialFindOperator}(${dataset1GeomSQL}, ${dataset2GeomSQL})`;

      // 22Feb2025 return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  // 11Aug2024
  function runBlockJsonInit() {
    const datasetOptions = getDatasetNamesList();
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "Find %1 %2 \n that %3 \n %4",
          args0: [
            {
              type: "field_dropdown",
              name: "DISTINCT_OPERATOR",
              options: [
                ["All", "ALL"],
                ["Unique", "DISTINCT"]
              ]
            },
            {
              type: "input_dummy",
              name: "DATASET1",
              options: datasetOptions
            },
            {
              type: "field_dropdown",
              name: "SPATIAL_FIND_OPERATOR",
              options: mSpatialOperatorOptions
            },
            {
              type: "input_dummy",
              name: "DATASET2",
              options: datasetOptions
            }
          ],
          // ? I don't like the structure of the UID that Blockly generates
          // 20May2024 id: Blockly.utils.genUid(),   // 20May2024
          data: { CustomID: mBlockID, BlockType: "SPATIAL", IsHeadBlock: true },
          extensions: [mExtensionName],
          nextStatement: null,
          // output: "String",
          colour: 150,
          tooltip: "Find spatial relationships between two datasets",
          helpUrl: ""
        });
      },
      // 15Sep2024
      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
        const datasetOptions = getDatasetNamesList();

        const updateDropdown = (field, options) => {
          const currentValue = field.getValue();
          field.menuGenerator_ = options;

          // Check if the current value exists in the new options
          const valueExists = options.some(
            (option) => option[1] === currentValue
          );

          if (valueExists) {
            // If the current value still exists, keep it
            field.setValue(currentValue);
          } else {
            // If the current value doesn't exist, set to the first option
            field.setValue(options[0][1]);
          }

          field.forceRerender();
        };

        // Update DATASET1
        const dataset1DDL = this.getField("DATASET1");
        updateDropdown(dataset1DDL, datasetOptions);

        // Update DATASET2
        const dataset2DDL = this.getField("DATASET2");
        updateDropdown(dataset2DDL, datasetOptions);
      }
    };
  }

  function createBlock() {
    runBlockJsonInit(); // 11Aug2024

    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  /*  // 15Sep2024
   publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit(); // 11Aug2024

    // ? Re-render the workspace
    Blockly.getMainWorkspace().render();
  };
 */

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mDatasetList = config.DatasetList;
    mToolsCategory = config.ToolsCategory;
    // 27Sep2024 mBlockID = mHelperUtil.generateShortGUID(); // 20May2024
    mBlockID =
      config.CustomID && config.CustomID !== null
        ? config.CustomID
        : mHelperUtil.generateShortGUID(); // 27Sep2024
    Blockly.setLocale(En);
    registerExtension();
    createBlock();
  };

  return publicAPI;
}
export default SpatialFindJoinBlock;
