import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function AggregationFindGroupByBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "aggregation_find_groupby_block"; // 09Feb2025
  let mExtensionName = "aggregation_find_groupby_extension";

  const mDatasetOriginTypes = {
    // 02Feb2025 External: "External",
    Remote: "Remote", // 02Feb2025
    Local: "Local", // 02Feb2025
    Block: "Block",
    Workflow: "Workflow",
    WorkflowStep: "WorkflowStep"
  };

  const mAggregateOperatorOptions = [
    ["Average", "AVG"],
    ["Total Number", "COUNT"],
    ["Sum", "SUM"],
    ["Minimum", "MIN"],
    ["Maximum", "MAX"]
  ];

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function registerExtension() {
    // ? Unregister the existing extension
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    // ? Register the new/updated extension
    Blockly.Extensions.register(mExtensionName, function () {
      this.data = {
        CustomID: mBlockID,
        BlockType: "AGGREGATION",
        IsHeadBlock: true
      }; // 20May2024

      const datasetDropdown1 = this.getField("DATASET1");
      this.getInput("COLUMNS_INPUT1").appendField(
        new Blockly.FieldDropdown(function () {
          const datasetName = datasetDropdown1.getValue();
          const options = getColumnsListOptions(datasetName);
          return options;
        }),
        "COLUMNS_FIELD1"
      );

      const datasetDropdown2 = this.getField("DATASET2");
      this.getInput("COLUMNS_INPUT2").appendField(
        new Blockly.FieldDropdown(function () {
          const datasetName = datasetDropdown2.getValue();
          const options = getColumnsListOptions(datasetName);
          return options;
        }),
        "COLUMNS_FIELD2"
      );
    });
  }

  function generateSQLCodeForBlock() {
    // ? Generate the JavaScript code for this block
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      let code = "";
      // ? This block requires that Dataset1 and Dataset2 are the same
     // 21Feb2025 const tblName = `tblHeadBlock_${mBlockID}`;
     const blockID = block.data.CustomID; // 21Feb2025
     const tblName = `tblHeadBlock_${blockID}`; // 21Feb2025
      const aggregationOperator = block.getFieldValue("AGGREGATE_OPERATOR");
      // ? Dataset1
      const datasetName = block.getFieldValue("DATASET1");
      const dataset = mDatasetList.find(function (d) {
        return d.Name === datasetName;
      });
      // ? Column1
      let columnName1 = block.getFieldValue("COLUMNS_FIELD1");
      const column1 = dataset.SelColumnsList.find(function (d) {
        return d.ColumnName === columnName1;
      });

      // ? Column2, get from dataset1 (as we are grouping by it)
      let columnName2 = block.getFieldValue("COLUMNS_FIELD2");
      const column2 = dataset.SelColumnsList.find(function (d) {
        return d.ColumnName === columnName2;
      });

      // 09Feb2025
      let selColumnSQLSyntax;
      if (column1.ColumnType === "string" || column1.ColumnType === "VARCHAR") {
        selColumnSQLSyntax = `${aggregationOperator} (CAST(${columnName1} AS FLOAT)) AS ${columnName1}`; // ? All Operators need numeric column type
      } else {
        selColumnSQLSyntax = `${aggregationOperator}(${columnName1})`;
      }

      // ? Add where claue to exclude invalid values ,09Feb2025
      const whereClause = `WHERE ${columnName1} IS NOT NULL AND ${columnName1} != '' AND ${columnName1} ~ '^[0-9]+(\.[0-9]+)?$'`;

      /*  // 11Feb2025
       let readDatasetSQL;
      if (dataset.Origin === mDatasetOriginTypes.Remote) {
        readDatasetSQL = `read_parquet('${dataset.Url}')`;
      } else if (dataset.Origin === mDatasetOriginTypes.Block) {
        readDatasetSQL = dataset.TableName;
      } */
      // 11Feb2025
      const readDatasetSQL = dataset.TableName; // 11Feb2025

      code = ` Create Or Replace Table ${tblName} As SELECT ${columnName2}, ${selColumnSQLSyntax} FROM ${readDatasetSQL} ${whereClause}  GROUP BY ${columnName2} ORDER BY ${columnName2} `;

      // 22Feb2025 return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  function getColumnsListOptions(newDatasetName) {
    const dataset = mDatasetList.find(function (d) {
      return d.Name === newDatasetName;
    });
    const datasetColumnsOptions = [];
    for (let i = 0; i < dataset.SelColumnsList.length; i += 1) {
      datasetColumnsOptions.push([
        dataset.SelColumnsList[i].ColumnName,
        dataset.SelColumnsList[i].ColumnName
      ]);
    }
    return datasetColumnsOptions;
  }

  function getDatasetNamesList() {
    const datasetOptions = [];
    for (let i = 0; i < mDatasetList.length; i += 1) {
      datasetOptions.push([mDatasetList[i].Name, mDatasetList[i].Name]);
    }

    return datasetOptions;
  }

  function runBlockJsonInit() {
    const datasetOptions = getDatasetNamesList();
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "Find %1 of %2::%3 \n for each unique value of %4::%5",
          args0: [
            {
              type: "field_dropdown",
              name: "AGGREGATE_OPERATOR",
              options: mAggregateOperatorOptions
            },
            {
              type: "field_dropdown",
              name: "DATASET1",
              options: datasetOptions
            },
            {
              type: "input_dummy",
              name: "COLUMNS_INPUT1"
            },
            {
              type: "field_dropdown",
              name: "DATASET2",
              options: datasetOptions
            },
            {
              type: "input_dummy",
              name: "COLUMNS_INPUT2"
            }
          ],
          // 20May2024 id: Blockly.utils.genUid(),   // 20May2024
          data: {
            CustomID: mBlockID,
            BlockType: "AGGREGATION",
            IsHeadBlock: true
          }, // ? I don't like the structure of the UID that Blockly generates
          extensions: [mExtensionName],
          colour: 50,
          tooltip: "tooltip text",
          helpUrl: ""
        });

        const datasetDropdown1 = this.getField("DATASET1");
        const columnsInput1 = this.getInput("COLUMNS_INPUT1");
        let datasetColumnsList1;

        // ? Add a change event listener to the Dataset dropdown field
        datasetDropdown1.setValidator(function (newDatasetName) {
          columnsInput1.removeField("COLUMNS_FIELD1");
          columnsInput1.appendField(
            new Blockly.FieldDropdown(function () {
              datasetColumnsList1 = getColumnsListOptions(newDatasetName);
              return datasetColumnsList1;
            }),
            "COLUMNS_FIELD1"
          );
        });

        const datasetDropdown2 = this.getField("DATASET2");
        const columnsInput2 = this.getInput("COLUMNS_INPUT2");
        let datasetColumnsList2;

        // ? Add a change event listener to the Dataset dropdown field
        datasetDropdown2.setValidator(function (newDatasetName) {
          columnsInput2.removeField("COLUMNS_FIELD2");
          columnsInput2.appendField(
            new Blockly.FieldDropdown(function () {
              datasetColumnsList2 = getColumnsListOptions(newDatasetName);
              return datasetColumnsList1;
            }),
            "COLUMNS_FIELD2"
          );
        });
      },
      // 15Sep2024
      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
        const datasetOptions = getDatasetNamesList();

        const updateDropdown = (field, options) => {
          const currentValue = field.getValue();
          field.menuGenerator_ = options;

          // Check if the current value exists in the new options
          const valueExists = options.some(
            (option) => option[1] === currentValue
          );

          if (valueExists) {
            // If the current value still exists, keep it
            field.setValue(currentValue);
          } else {
            // If the current value doesn't exist, set to the first option
            field.setValue(options[0][1]);
          }

          field.forceRerender();
        };

        // Update DATASET1
        const dataset1DDL = this.getField("DATASET1");
        updateDropdown(dataset1DDL, datasetOptions);

        // Update DATASET2
        const dataset2DDL = this.getField("DATASET2");
        updateDropdown(dataset2DDL, datasetOptions);
      }
    };
  }

  function createBlock() {
    runBlockJsonInit();

    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit();

    // ? Re-render the workspace
    Blockly.getMainWorkspace().render();
  };

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mToolsCategory = config.ToolsCategory;
    mDatasetList = config.DatasetList;
    mBlockID = mHelperUtil.generateShortGUID();
    Blockly.setLocale(En);
    registerExtension();
    createBlock();
  };

  return publicAPI;
}
export default AggregationFindGroupByBlock;
