import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function SpatialInlikeBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "spatial_inlike_block";
  let mExtensionName = "spatial_inlike_extension";

  const mInLikeOperatorOptions = [
    ["Has at least one of", "IN"],
    ["Does not have any", "NOT IN"],
    ["Matches the pattern", "LIKE"]
  ];

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function registerExtension() {
    // ? Unregister the existing extension
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    // ? Register the new/updated extension
    Blockly.Extensions.register(mExtensionName, function () {
      this.data = {
        CustomID: mBlockID,
        BlockType: "SPATIAL",
        IsHeadBlock: false
      };
    });
  }

  // 07Sep2024
  function getSpatialFindBlock(startBlock) {
    // Check if the starting block is valid
    if (!startBlock) {
      return null;
    }

    // Initialize the current block to the starting block
    let currentBlock = startBlock;

    // Traverse up the chain of previous blocks
    while (currentBlock) {
      if (
        currentBlock.type === "spatial_find_join_block" ||
        currentBlock.type === "spatial_find_withindistance_frompoint_block" ||
        currentBlock.type === "spatial_find_buffer_block"
      ) {
        return currentBlock;
      }

      // Move to the previous block
      currentBlock = currentBlock.getPreviousBlock();
    }

    return null;
  }
  // 07Sep2024
  function getDatasetAlias(block, datasetName) {
    // ? get the dataset alias
    let datasetAlias = "";

    let spatialFindDataset1Name;
    let spatialFindDataset2Name;
    const spatialFindBlock = getSpatialFindBlock(block);
    if (
      spatialFindBlock &&
      spatialFindBlock.type === "spatial_find_join_block"
    ) {
      spatialFindDataset1Name = spatialFindBlock.getFieldValue("DATASET1");
      spatialFindDataset2Name = spatialFindBlock.getFieldValue("DATASET2");
    }

    if (datasetName === spatialFindDataset1Name) {
      datasetAlias = "d1.";
    } else if (datasetName === spatialFindDataset2Name) {
      datasetAlias = "d2.";
    }

    return datasetAlias;
  }

  // 07Sep2024
  function addQuotesToCSV(csvString) {
    // Split the string into an array
    const values = csvString.split(",");

    // Trim whitespace and add quotes to each value
    const quotedValues = values.map(function (value) {
      return "'".concat(value.trim(), "'");
    });

    // Join the values back into a string
    return quotedValues.join(",");
  }

  // 10Sep2024
  function getAndPrefix(block) {
    let andPrefix = "";
    const spatialFindBlock = getSpatialFindBlock(block);
    if (
      spatialFindBlock &&
      spatialFindBlock.type === "spatial_find_join_block"
    ) {
      andPrefix = "";
    }
    if (
      spatialFindBlock &&
      spatialFindBlock.type === "spatial_find_withindistance_frompoint_block"
    ) {
      andPrefix = " AND ";
      if (nextBlock && nextBlock.type === "spatial_andor_block") {
        andPrefix += "(";
      }
    }

    return andPrefix;
  }

  function generateSQLCodeForBlock() {
    // ? Generate the JavaScript code for this block
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      let code = "";

      // ? inlike Operator
      const inlikeOperator = block.getFieldValue("INLIKE_OPERATOR");
      // ? get connected block,  // 12Aug2024
      const previousBlock = block.previousConnection.targetBlock();
      const nextBlock = block.nextConnection.targetBlock(); // 12Sep2024
      // ? Dataset
      const previousBlockDatasetName = previousBlock.getFieldValue("DATASET");
      const previousBlockDataset = mDatasetList.find(function (d) {
        return d.Name === previousBlockDatasetName;
      });
      // ? Column
      let previousBlockColumnName =
        previousBlock.getFieldValue("COLUMNS_FIELD");
      const previousBlockColumn = previousBlockDataset.SelColumnsList.find(
        function (d) {
          return d.ColumnName === previousBlockColumnName;
        }
      );

      // ? WHERE block
      if (previousBlock.type === "spatial_where_block") {
        const datasetAlias = getDatasetAlias(
          previousBlock,
          previousBlockDatasetName
        ); // 06Sep2024
        const andPrefix = getAndPrefix(previousBlock); // 10Sep2024
        const closingBracket =
          andPrefix.includes("(") && !nextBlock ? " ) " : ""; // ? last block, // 12Sep2024

        if (inlikeOperator === "IN" || inlikeOperator === "NOT IN") {
          if (
            previousBlockColumn.ColumnType === "string" ||
            previousBlockColumn.ColumnType === "VARCHAR"
          ) {
            const inputVal = block.getFieldValue("VALUE"); // 07Sep2024
            const quotedInputVal = addQuotesToCSV(inputVal); // 07Sep2024
            // 07Sep2024 code = ` ${datasetAlias}${previousBlockColumnName} ${inlikeOperator} ('${block.getFieldValue("VALUE")}')`;
            code = ` ${andPrefix} ${datasetAlias}${previousBlockColumnName} ${inlikeOperator} (${quotedInputVal})${closingBracket}`; // 07Sep2024
          } else {
            code = ` ${andPrefix} ${datasetAlias}${previousBlockColumnName} ${inlikeOperator} (${block.getFieldValue("VALUE")})${closingBracket}`;
          }
        }

        if (inlikeOperator === "LIKE") {
          code = ` ${andPrefix} ${datasetAlias}${previousBlockColumnName} ${inlikeOperator} '${block.getFieldValue("VALUE")}'${closingBracket}`;
        }
      }

      // ? ANDOR block
      if (previousBlock.type === "spatial_andor_block") {
        const andOrOperator = previousBlock.getFieldValue("ANDOR_OPERATOR");
        const datasetAlias = getDatasetAlias(
          previousBlock,
          previousBlockDatasetName
        ); // 06Sep2024
        let closingBracket = "";
        const spatialFindBlock = getSpatialFindBlock(previousBlock);

        if (
          spatialFindBlock &&
          spatialFindBlock.type ===
            "spatial_find_withindistance_frompoint_block" &&
          nextBlock === null
        ) {
          closingBracket = " ) ";
        }

        if (inlikeOperator === "IN" || inlikeOperator === "NOT IN") {
          if (
            previousBlockColumn.ColumnType === "string" ||
            previousBlockColumn.ColumnType === "VARCHAR"
          ) {
            const inputVal = block.getFieldValue("VALUE"); // 07Sep2024
            const quotedInputVal = addQuotesToCSV(inputVal); // 07Sep2024
            // 07Sep2024 code = ` ${datasetAlias}${previousBlockColumnName} ${inlikeOperator} ('${block.getFieldValue("VALUE")}')`;
            code = ` ${andOrOperator}  ${datasetAlias}${previousBlockColumnName} ${inlikeOperator} (${quotedInputVal})${closingBracket}`; // 07Sep2024
          } else {
            code = ` ${andOrOperator}  ${datasetAlias}${previousBlockColumnName} ${inlikeOperator} (${block.getFieldValue("VALUE")})${closingBracket}`;
          }
        }

        if (inlikeOperator === "LIKE") {
          code = ` ${andOrOperator}  ${datasetAlias}${previousBlockColumnName} ${inlikeOperator} '${block.getFieldValue("VALUE")}'${closingBracket}`;
        }
      }

      // 22Feb2025 return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  function runBlockJsonInit() {
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "%1 %2",
          args0: [
            {
              type: "field_dropdown",
              name: "INLIKE_OPERATOR",
              options: mInLikeOperatorOptions
            },
            {
              type: "field_input",
              name: "VALUE",
              spellcheck: false
            }
          ],
          // 20May2024 id: Blockly.utils.genUid(),   // 20May2024
          data: {
            CustomID: mBlockID,
            BlockType: "SPATIAL",
            IsHeadBlock: false
          }, // ? I don't like the structure of the UID that Blockly generates
          extensions: [mExtensionName],
          previousStatement: null,
          nextStatement: null,
          colour: 150,
          tooltip: "tooltip text",
          helpUrl: ""
        });
      },
      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
      }
    };
  }

  function createBlock() {
    runBlockJsonInit();

    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit();

    // ? Re-render the workspace
    Blockly.getMainWorkspace().render();
  };

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mToolsCategory = config.ToolsCategory;
    mDatasetList = config.DatasetList;
    mBlockID = mHelperUtil.generateShortGUID();
    Blockly.setLocale(En);
    registerExtension();
    createBlock();
  };

  return publicAPI;
}
export default SpatialInlikeBlock;
