import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function MapCategoriesBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "viz_map_categories_value_block";
  let mExtensionName = "viz_map_categories_value_extension";
  let mDBConn;

  // ? colors from https://colorbrewer2.org/#type=qualitative&scheme=Paired&n=12
  const mColors = [
    "#a6cee3",
    "#1f78b4",
    "#b2df8a",
    "#33a02c",
    "#fb9a99",
    "#e31a1c",
    "#fdbf6f",
    "#ff7f00",
    "#cab2d6",
    "#6a3d9a",
    "#ffff99",
    "#b15928"
  ];
  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function getDatasetNamesList() {
    // ? return datasets that have the property HasGeometry = true (spatial datasets only)
    const datasetOptions = mDatasetList
      .filter((dataset) => dataset.HasGeometry === true)
      .map((dataset) => [dataset.Name, dataset.Name]);
    return datasetOptions;
    // 14Feb2025 return mDatasetList.map((dataset) => [dataset.Name, dataset.Name]);
  }

  function getColumnsListOptions(datasetName) {
    const dataset = mDatasetList.find((d) => d.Name === datasetName);
    if (!dataset) {
      return [["Select Column", "SELECT_COLUMN"]];
    }
    return [
      ["Select Column", "SELECT_COLUMN"],
      ...dataset.SelColumnsList.map((col) => [col.ColumnName, col.ColumnName])
    ];
  }

  async function getUniqueValues(tableName, columnName) {
    try {
      const query = `SELECT DISTINCT ${columnName} FROM ${tableName} ORDER BY ${columnName}`;
      const result = await mDBConn.query(query);
      const valuesArr = result.toArray().map(Object.fromEntries);
      return valuesArr.map((row) => row[columnName]);
    } catch (error) {
      console.error("Error fetching unique values:", error);
      return [];
    }
  }

  function registerExtension() {
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    Blockly.Extensions.register(mExtensionName, function () {
      this.data = {
        CustomID: mBlockID,
        BlockType: "VIZ",
        IsHeadBlock: true,
        userDefinedColors: {}
      };

      const datasetField = this.getField("DATASET");
      const columnField = this.getField("COLUMN");

      datasetField.setValidator((newValue) => {
        this.updateColumnOptions();
        columnField.setValue("SELECT_COLUMN");
        this.updateUniqueValues();
        return newValue;
      });

      columnField.setValidator((newValue) => {
        if (newValue !== "SELECT_COLUMN") {
          setTimeout(() => this.updateUniqueValues(), 0);
        } else {
          this.removeInputs("COLOR_MAPPING");
          if (this.rendered) {
            this.render();
            this.bumpNeighbours();
          }
        }
        return newValue;
      });
    });
  }

  function runBlockJsonInit() {
    const datasetOptions = getDatasetNamesList();
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "Map colors for %1",
          args0: [
            {
              type: "field_dropdown",
              name: "DATASET",
              options: datasetOptions
            }
          ],
          message1: "Column %1",
          args1: [
            {
              type: "field_dropdown",
              name: "COLUMN",
              options: [["Select Column", "SELECT_COLUMN"]]
            }
          ],
          message2: "Color mappings:",
          args2: [],
          data: {
            CustomID: mBlockID,
            BlockType: "VIZ",
            IsHeadBlock: true
          },
          extensions: [mExtensionName],
          colour: 250,
          tooltip: "Map colors to unique values in a column",
          helpUrl: ""
        });
        this.setInputsInline(false);
        const datasetDropdown = this.getField("DATASET");
        const columnDropdown = this.getField("COLUMN");
        let datasetColumnsList;

        // ? Add a change event listener to the Dataset dropdown field
        datasetDropdown.setValidator(function (newDatasetName) {
          datasetColumnsList = getColumnsListOptions(newDatasetName);
          /*  // 06Mar2025
          columnDropdown.menuGenerator_ = [
            ["Select Column", "SELECT_COLUMN"],
            ...datasetColumnsList
          ]; */
          columnDropdown.menuGenerator_ = datasetColumnsList; // 06Mar2025
        });
      },

      /*  updateDatasetOptions: function () {
        const datasetOptions = getDatasetNamesList();
        this.getField("DATASET").menuGenerator_ = [
          ["Select Dataset", "SELECT_DATASET"],
          ...datasetOptions
        ];
      }, */

      updateFieldDropdownList: function (config) {
        const updateDropdown = (field, options) => {
          const currentValue = field.getValue();
          field.menuGenerator_ = options;

          // Check if the current value exists in the new options
          const valueExists = options.some(
            (option) => option[1] === currentValue
          );

          if (valueExists) {
            // If the current value still exists, keep it
            field.setValue(currentValue);
          } else {
            // If the current value doesn't exist, set to the first option
            field.setValue(options[0][1]);
          }

          field.forceRerender();
        };

        // Update DATASET
        mDatasetList = config.DatasetList;
        const datasetOptions = getDatasetNamesList();
        const datasetDDL = this.getField("DATASET");
        updateDropdown(datasetDDL, datasetOptions);
      },

      /*  updateColumnOptions: function () {
        const datasetName = this.getFieldValue("DATASET");
        const columnOptions = getColumnsListOptions(datasetName);
        this.getField("COLUMN").menuGenerator_ = columnOptions;
      }, */

      updateUniqueValues: async function (d, i) {
        const datasetName = this.getFieldValue("DATASET");
        let columnName = this.getFieldValue("COLUMN");

        if (columnName === "SELECT_COLUMN") {
          this.removeInputs("COLOR_MAPPING");
          return;
        }

        const dataset = mDatasetList.find((d) => d.Name === datasetName);
        const tableName = dataset.TableName;
        const uniqueValues = await getUniqueValues(tableName, columnName);

        // Remove existing color mapping inputs
        this.removeInputs("COLOR_MAPPING");

        // Add new inputs for each unique value
        uniqueValues.forEach((value, index) => {
          const input = this.appendDummyInput(`COLOR_MAPPING_${index}`);

          // Add right-aligned label
          input.appendField(
            new Blockly.FieldLabel(value.toString()),
            `LABEL_${index}`
          );

          // Add some space
          input.appendField("  ");

          /*  // 11Apr2025
          // Add color input with a color from mColors array
          const colorIndex = index % mColors.length;
          input.appendField(
            new Blockly.FieldTextInput(mColors[colorIndex]),
            `COLOR_${index}`
          ); */

          // 11Apr2025
          // Use user-defined color if available, otherwise use default color
          const colorIndex = index % mColors.length;
          const defaultColor = mColors[colorIndex];
          const userColor = this.data.userDefinedColors[value] || defaultColor;

          const colorField = new Blockly.FieldTextInput(userColor);
          colorField.setValidator((newColor) => {
            // Store the user-defined color when it changes
            this.data.userDefinedColors[value] = newColor;
            return newColor;
          });

          input.appendField(colorField, `COLOR_${index}`);

          // Set the alignment of the entire input to right
          input.setAlign(1); // ? 0-Center,1-Right,2-Left
        });

        if (this.rendered) {
          this.render();
          this.bumpNeighbours();
        }
      },

      removeInputs: function (prefix) {
        let i = 0;
        while (this.getInput(`${prefix}_${i}`)) {
          this.removeInput(`${prefix}_${i}`);
          i++;
        }
      }
    };
  }

  function escapeSQLString(str) {
    return str.replace(/'/g, "''"); //? escape single quote
  }

  function generateSQLCodeForBlock() {
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      const blockID = block.data.CustomID;
      const tblName = `tblHeadBlock_${blockID}`;
      const datasetName = block.getFieldValue("DATASET");
      const dataset = mDatasetList.find((d) => d.Name === datasetName);
      const datasetTableName = dataset.TableName;
      const columnName = block.getFieldValue("COLUMN");

      let colorMappings = [];
      let i = 0;
      while (true) {
        const labelField = block.getField(`LABEL_${i}`);
        const colorField = block.getField(`COLOR_${i}`);
        if (!labelField || !colorField) {
          break;
        }
        const value = escapeSQLString(labelField.getText());
        const color = colorField.getValue();
        colorMappings.push({ value, color });
        i++;
      }

      // If no color mappings are found, return an empty result, // 06Mar2025
      if (colorMappings.length === 0) {
        const emptyObj = {
          sqlCode: "",
          categoryColors: [],
          categoryColumn: columnName
        };
        return JSON.stringify(emptyObj);
      }

      const caseStatements = colorMappings
        .map(
          ({ value, color }) =>
            `WHEN ${columnName} = '${value}' THEN '${color}'`
        )
        .join("\n        ");

      const code = `
      -- Create a copy of the original dataset
      CREATE OR REPLACE TABLE ${tblName} AS SELECT * FROM ${datasetTableName};
  
      -- Add the category_color column to the copied table
      ALTER TABLE ${tblName} ADD COLUMN category_color TEXT;
  
      -- Update category_color column based on the mapping
      UPDATE ${tblName}
      SET category_color = CASE
        ${caseStatements}
        ELSE NULL -- Set NULL for values not in the mapping
      END;
  
      -- Select all columns including the new category_color
      SELECT *, category_color FROM ${tblName};
      `;

      // Return an object with both the SQL code and the category-color JSON
      const jsonObj = {
        sqlCode: code,
        categoryColors: colorMappings,
        categoryColumn: columnName
      };
      return JSON.stringify(jsonObj);
    };
  }

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function createBlock() {
    runBlockJsonInit();
    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit();
    Blockly.getMainWorkspace().render();
  };

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mToolsCategory = config.ToolsCategory;
    mDatasetList = config.DatasetList;
    mBlockID = mHelperUtil.generateShortGUID();
    mDBConn = config.DatabaseConnection;
    Blockly.setLocale(En);
    registerExtension();
    createBlock();
  };

  return publicAPI;
}

export default MapCategoriesBlock;
