  function addTableRows(tableBody) {
    let td;
    let row;
    let trRow;

    for (let i = 0; i < mConfig.TableData.length; i += 1) {
      row = mConfig.TableData[i];

      trRow = document.createElement("TR");
      for (let j = 0; j < mConfig.ColumnsList.length; j += 1) {
        td = document.createElement("TD");
        td.innerHTML = row[mConfig.ColumnsList[j].ColumnName];
        trRow.appendChild(td);
      }

      tableBody.appendChild(trRow);
    }

    return tableBody;
  }

  // 07Jan2025
  //? Function to check if a string starts with zero
  function isFirstCharZero(str) {
    return /^0/.test(str);
  }

  // 12Dec2024
  function detectColumnType(data, key) {
    const sample = data.slice(0, 100).map((row) => row[key]);

    // if (sample.every((val) => typeof val === "number")) return "num";
    if (sample.every((val) => val instanceof Date)) return "date";
    if (sample.every((val) => typeof val === "boolean")) return "bool";

    /*  // 07Jan2025
   //  const isNumeric = sample.every(
      (val) => !isNaN(parseFloat(val)) && isFinite(val)
    ); */
    // 07Jan2025
    const isNumeric = sample.every((val) => {
      if (typeof val === "bigint") return true;
      (val) =>
        !isNaN(parseFloat(val)) && isFinite(val) && !isFirstCharZero(val); // 07Jan2025
    });

    /*  // 07Jan2025
     const isInteger =
      isNumeric && sample.every((val) => Number.isInteger(parseFloat(val))); */
    // 07Jan2025
    const isInteger =
      isNumeric &&
      sample.every((val) => {
        if (typeof val === "bigint") return true;
        return Number.isInteger(parseFloat(val));
      });

    /*  // 07Jan2025
     if (isNumeric && isInteger) {
      return "int";
    }
    if (isNumeric) {
      return "float";
    } */
    // 07Jan2025
    if (isNumeric) {
      if (isInteger) {
        if (sample.some((val) => typeof val === "bigint")) {
          return "bigint";
        }
        return "int";
      }
      return "float";
    }

    return "string";
  }

  // 12Dec2024
  function generateColumnDefs(columns) {
    return columns.map((col, index) => {
      const def = { targets: index, className: "dt-body-left" };

      switch (col.type) {
        /*   case "num":
          def.render = datatables.render.number(",", ".", 2); */
        case "int":
          def.render = datatables.render.number(",", ".", 0);
          break;
        case "float":
          def.render = datatables.render.number(",", ".", 2);
          break;
        case "date":
          def.render = datatables.render.date();
          break;
        case "bool":
          def.render = (data) => (data ? "Yes" : "No");
          break;
      }

      return def;
    });
  }

