    const trHeader = createTableHeader();
    tableHead.appendChild(trHeader);

    tableBody = addTableRows(tableBody);

    tableFragment.appendChild(tableHead);
    tableFragment.appendChild(tableBody);
    table.appendChild(tableFragment);

