import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";
// 30Aug2024 import MinWidthTextInput from "../../../classes/blocklytextinputclass";

function SpatialFindBufferBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "spatial_find_buffer_block";
  let mExtensionName = "spatial_find_buffer_extension";

  const mDatasetOriginTypes = {
    // 02Feb2025 External: "External",
    Remote: "Remote", // 02Feb2025
    Local: "Local", // 02Feb2025
    Block: "Block",
    Workflow: "Workflow",
    WorkflowStep: "WorkflowStep"
  };

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function registerExtension() {
    // ? Unregister the existing extension
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    // ? Register the new/updated extension
    Blockly.Extensions.register(mExtensionName, function () {
      // 26Aug2024 const datasetOptions = getDatasetNamesList();
      this.data = {
        CustomID: mBlockID,
        BlockType: "SPATIAL",
        IsHeadBlock: true
      }; // 20May2024

      /*  // 30Aug2024
      this.getInput("DISTANCE").appendField(
        new MinWidthTextInput("", null, 100),
        "DISTANCE"
      ); */
    });
  }

  function formatColumnsForSQL(columnsList) {
    // ? Map over the columns array and format each column name
    const formattedColumns = columnsList.map(function (column) {
      // ? Trim any leading/trailing whitespace
      const columnName = column.trim();

      // ? Wrap the column name in square brackets if it contains spaces
      if (columnName.includes(" ")) {
        return `[${columnName}]`;
      } else {
        return columnName;
      }
    });

    let sqlStr = ""; //
    for (let i = 0; i < formattedColumns.length; i++) {
      sqlStr += `${formattedColumns[i]}`;
      if (i < formattedColumns.length - 1) {
        sqlStr += ", ";
      }
    }

    return sqlStr;
  }

  // 14Jan2025
  function getGeomColName(columnsList) {
    const geomCol = columnsList.find(function (col) {
      return col.ColumnType.toUpperCase() === "GEOMETRY";
    });
    if (geomCol) {
      return geomCol.ColumnName;
    }
    return "No Geometry Column Found";
  }

  function generateSQLCodeForBlock() {
    // ? Generate the JavaScript code for this block
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      let code = "";
      // 21Feb2025 const tblName = `tblHeadBlock_${mBlockID}`;
      const blockID = block.data.CustomID; // 21Feb2025
      const tblName = `tblHeadBlock_${blockID}`; // 21Feb2025
      const bufferDistanceMiles = parseFloat(block.getFieldValue("DISTANCE"));
      const bufferDistanceMeters = +bufferDistanceMiles * 1609.34; //? Convert miles to meters
      const datasetName = block.getFieldValue("DATASET");
      // ? DATASET
      const dataset = mDatasetList.find(function (d) {
        return d.Name === datasetName;
      });
      const datasetGeomColumnName = getGeomColName(dataset.SelColumnsList); // 14Jan2025
      // 14Jan2025 const datasetSQLStr = formatColumnsForSQL(datasetSelColumnsList);
      // 14Jan2025
      let datasetSQLStr;
      if (dataset.SelColumnsList.length < dataset.ColumnsList) {
        // 14Jan2025
        // ? Remove 'geometry' column
        const datasetSelColumnsList = dataset.SelColumnsList.filter(
          function (d) {
            // 14Jan2025 return d.ColumnName !== "geometry";
            return d.ColumnType.toUpperCase() !== "GEOMETRY"; // 14Jan2025
          }
        ).map(function (a) {
          return a.ColumnName;
        });
        datasetSQLStr = formatColumnsForSQL(datasetSelColumnsList);
      } else {
        datasetSQLStr = `* EXCLUDE(${datasetGeomColumnName})`;
      }

      /*  // 11Feb2025
       let readDatasetSQL;
      if (dataset.Origin === mDatasetOriginTypes.Remote) {
        readDatasetSQL = `read_parquet('${dataset.Url}')`;
      } else if (dataset.Origin === mDatasetOriginTypes.Block) {
        readDatasetSQL = dataset.TableName;
      } */
      // 11Feb2025
      const readDatasetSQL = dataset.TableName; // 11Feb2025

      /*  // ? 12Feb2025
      let datasetGeomSQL;
      if (dataset.CRS !== "EPSG:3857") {
        // 14Jan2025 datasetGeomSQL = `ST_Transform(geometry, '${dataset.CRS}', 'EPSG:3857')`; // 26Sep2024
        datasetGeomSQL = `ST_Transform(${datasetGeomColumnName}, '${dataset.CRS}', 'EPSG:3857')`; // 26Sep2024
      } else {
        // 14Jan2025 datasetGeomSQL = `geometry`; // 26Sep2024
        datasetGeomSQL = `${datasetGeomColumnName}`; // 26Sep2024
      }

      // 14Sep2024
      code = `Create Or Replace Table ${tblName} As SELECT ${datasetSQLStr}, ST_Buffer(${datasetGeomSQL}, ${bufferDistanceMeters}) As buffer_geometry FROM ${readDatasetSQL} `; */

      // ? 12Feb2025
      // ? For spatial analysis across the entire United States, a good choice would be the USA Contiguous Albers Equal Area Conic projection (EPSG:5070). Here's why it's appropriate:
      // ? 1.Equal Area: It preserves area across the entire country, which is crucial for accurate spatial analysis, especially when calculating areas or densities.
      // ? 2.Designed for the US: It's specifically designed to minimize distortion across the contiguous United States.
      // ? 3.Widely used: It's commonly used by US federal agencies, including the US Geological Survey, for national-scale mapping and analysis.
      // ? 4.Covers all states: While optimized for the contiguous states, it also includes Alaska and Hawaii (though with more distortion for these non-contiguous areas).
      code = `Create Or Replace Table ${tblName} As SELECT ${datasetSQLStr}, ST_Buffer(${datasetGeomColumnName}, ${bufferDistanceMeters}) As buffer_geometry FROM ${readDatasetSQL} `; // ? Should not use EPSG:3857 for spatial analysis. For universal storage, use EPSG:4326. If a local coordinate system cannot
      // ? be used for analysis, then project all USA based data to EPSG:5070 and then do the analysis. EPSG:5070 can be used as a common projection for USA based data // 12Feb2025

      // return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  function getDatasetNamesList() {
    const datasetOptions = [];
    for (const element of mDatasetList) {
      datasetOptions.push([element.Name, element.Name]);
    }

    return datasetOptions;
  }

  function runBlockJsonInit() {
    const datasetOptions = getDatasetNamesList();
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "Create a circular zone (radius) \n of  %1 miles around %2",
          args0: [
            {
              type: "field_input",
              name: "DISTANCE",
              spellcheck: false
            },
            // 30Aug2024 { type: "input_dummy", name: "DISTANCE" },
            {
              type: "field_dropdown",
              name: "DATASET",
              options: datasetOptions
            }
          ],
          // 20May2024 id: Blockly.utils.genUid(),   // 20May2024
          data: { CustomID: mBlockID, BlockType: "SPATIAL", IsHeadBlock: true }, // ? I don't like the structure of the UID that Blockly generates
          extensions: [mExtensionName],
          colour: 150,
          nextStatement: null,
          tooltip: "tooltip text",
          helpUrl: ""
        });
      },
      // 15Sep2024
      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
        const datasetOptions = getDatasetNamesList();

        const updateDropdown = (field, options) => {
          const currentValue = field.getValue();
          field.menuGenerator_ = options;

          // Check if the current value exists in the new options
          const valueExists = options.some(
            (option) => option[1] === currentValue
          );

          if (valueExists) {
            // If the current value still exists, keep it
            field.setValue(currentValue);
          } else {
            // If the current value doesn't exist, set to the first option
            field.setValue(options[0][1]);
          }

          field.forceRerender();
        };

        // Update DATASET
        const datasetDDL = this.getField("DATASET");
        updateDropdown(datasetDDL, datasetOptions);
      }
    };
  }

  /*  function registerCustomField() {
    // ? Register the custom text input field
    Blockly.fieldRegistry.register("MinWidthTextInput", MinWidthTextInput);
  } */

  function createBlock() {
    runBlockJsonInit();

    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  /*  // 15Sep2024
   publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit();

    // ? Re-render the workspace
    Blockly.getMainWorkspace().render();
  }; */

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mToolsCategory = config.ToolsCategory;
    mDatasetList = config.DatasetList;
    mBlockID = mHelperUtil.generateShortGUID();
    Blockly.setLocale(En);
    // 30Aug2024 //? this code is not creating a bigger text field//  registerCustomField();
    registerExtension();
    createBlock();
  };

  return publicAPI;
}
export default SpatialFindBufferBlock;
