import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function DataCombineBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "logic_data_combine_block";
  let mExtensionName = "logic_data_combine_extension";

  `The mJoinTypeOptions array defines three types of joins:
"Match all" (INNER JOIN): Returns only the rows that have matching values in both tables.
"Include all from first" (LEFT JOIN): Returns all rows from the left table, and the matched rows from the right table. If there's no match, the result is NULL on the right side.
"Include all from both" (FULL OUTER JOIN): Returns all rows when there is a match in either left or right table. If there's no match, it will still return the rows with NULL on the side that doesn't have a match.`;
  const mJoinTypeOptions = [
    ["Match all", "INNER"],
    ["Include all from first", "LEFT"],
    ["Include all from both", "FULL OUTER"]
  ];

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };

  publicAPI.getMediator = function () {
    return mMediator;
  };

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function registerExtension() {
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    Blockly.Extensions.register(mExtensionName, function () {
      this.data = { CustomID: mBlockID, BlockType: "LOGIC", IsHeadBlock: true };

      const datasetDropdown1 = this.getField("DATASET1");
      this.getInput("COLUMNS_INPUT1").appendField(
        new Blockly.FieldDropdown(function () {
          const datasetName = datasetDropdown1.getValue();
          return getColumnsListOptions(datasetName);
        }),
        "COLUMNS_FIELD1"
      );

      const datasetDropdown2 = this.getField("DATASET2");
      this.getInput("COLUMNS_INPUT2").appendField(
        new Blockly.FieldDropdown(function () {
          const datasetName = datasetDropdown2.getValue();
          return getColumnsListOptions(datasetName);
        }),
        "COLUMNS_FIELD2"
      );
    });
  }

  function generateSQLCodeForBlock() {
    javascriptGenerator.forBlock[mBlockName] = function (block) {
     // 21Feb2025 const tblName = `tblHeadBlock_${mBlockID}`;
     const blockID = block.data.CustomID; // 21Feb2025
     const tblName = `tblHeadBlock_${blockID}`; // 21Feb2025
      const joinType = block.getFieldValue("JOIN_TYPE");
      const datasetName1 = block.getFieldValue("DATASET1");
      const datasetName2 = block.getFieldValue("DATASET2");
      const columnName1 = block.getFieldValue("COLUMNS_FIELD1");
      const columnName2 = block.getFieldValue("COLUMNS_FIELD2");

      /*   const code = `
        CREATE OR REPLACE TABLE ${tblName} AS
        SELECT * FROM ${datasetName1}
        ${joinType} JOIN ${datasetName2}
        ON ${datasetName1}.${columnName1} = ${datasetName2}.${columnName2}
      `; */

      // 12Feb2025
      const dataset1 = mDatasetList.find(function (d) {
        return d.Name === datasetName1;
      });
      const geomColName1 = dataset1.GeomColName;

      const dataset2 = mDatasetList.find(function (d) {
        return d.Name === datasetName2;
      });
      const geomColName2 = dataset2.GeomColName;

      /* const code = `
      CREATE OR REPLACE TABLE ${tblName} AS
      SELECT * FROM ${dataset1.TableName}
      ${joinType} JOIN ${dataset2.TableName}
      ON ${dataset1.TableName}.${columnName1} = ${dataset2.TableName}.${columnName2}
    `; */
      let geometryClause = "";
      if (geomColName1 && geomColName2) {
        geometryClause = `, COALESCE(${dataset1.TableName}.${geomColName1}, ${dataset2.TableName}.${geomColName2}) AS geometry`;
      } else if (geomColName1) {
        geometryClause = `, ${dataset1.TableName}.${geomColName1} AS geometry`;
      } else if (geomColName2) {
        geometryClause = `, ${dataset2.TableName}.${geomColName2} AS geometry`;
      }

      const code = `
      CREATE OR REPLACE TABLE ${tblName} AS
      SELECT ${dataset1.TableName}.*, ${dataset2.TableName}.*${geometryClause}
      FROM ${dataset1.TableName}
      ${joinType} JOIN ${dataset2.TableName}
      ON ${dataset1.TableName}.${columnName1} = ${dataset2.TableName}.${columnName2}
    `;

      // 22Feb2025 return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  function getDatasetNamesList() {
    return mDatasetList.map((dataset) => [dataset.Name, dataset.Name]);
  }

  function getColumnsListOptions(datasetName) {
    const dataset = mDatasetList.find((d) => d.Name === datasetName);
    return dataset.SelColumnsList.map((column) => [
      column.ColumnName,
      column.ColumnName
    ]);
  }

  function runBlockJsonInit() {
    const datasetOptions = getDatasetNamesList();
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "Combine/Match %1 using column %2 with %3 using column %4 %5",
          args0: [
            {
              type: "field_dropdown",
              name: "DATASET1",
              options: datasetOptions
            },
            {
              type: "input_dummy",
              name: "COLUMNS_INPUT1"
            },
            {
              type: "field_dropdown",
              name: "DATASET2",
              options: datasetOptions
            },
            {
              type: "input_dummy",
              name: "COLUMNS_INPUT2"
            },
            {
              type: "field_dropdown",
              name: "JOIN_TYPE",
              options: mJoinTypeOptions
            }
          ],
          data: { CustomID: mBlockID, BlockType: "LOGIC", IsHeadBlock: true },
          extensions: [mExtensionName],
          previousStatement: null,
          nextStatement: null,
          colour: 200,
          tooltip: "Combine two datasets based on matching columns",
          helpUrl: ""
        });
      },
      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
        const datasetOptions = getDatasetNamesList();

        const updateDropdown = (field, options) => {
          const currentValue = field.getValue();
          field.menuGenerator_ = options;
          field.setValue(
            options.some((option) => option[1] === currentValue)
              ? currentValue
              : options[0][1]
          );
          field.forceRerender();
        };

        updateDropdown(this.getField("DATASET1"), datasetOptions);
        updateDropdown(this.getField("DATASET2"), datasetOptions);
      }
    };
  }

  function createBlock() {
    runBlockJsonInit();
    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  publicAPI.init = function (config) {
    mHelperUtil = new HelperUtil();
    mDatasetList = config.DatasetList;
    mToolsCategory = config.ToolsCategory;
    mBlockID = mHelperUtil.generateShortGUID();
    Blockly.setLocale(En);
    registerExtension();
    createBlock();
  };

  return publicAPI;
}

export default DataCombineBlock;
