import * as Blockly from "blockly/core";
import { javascriptGenerator } from "blockly/javascript";
import * as En from "blockly/msg/en";
import HelperUtil from "../../helperutils";

function FindBlock() {
  const publicAPI = {};
  let mMediator;
  let mBlockID;
  let mHelperUtil;
  let mToolsCategory;
  let mDatasetList;
  let mBlockName = "logic_find_block";
  let mExtensionName = "logic_find_extension";
  const mDatasetOriginTypes = {
    // 02Feb2025 External: "External",
    Remote: "Remote", // 02Feb2025
    Local: "Local", // 02Feb2025
    Block: "Block",
    Workflow: "Workflow",
    WorkflowStep: "WorkflowStep"
  };

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  function addBlockToToolsCategory() {
    mToolsCategory.contents.push({
      kind: "block",
      type: mBlockName
    });
  }

  function registerExtension() {
    // ? Unregister the existing extension
    if (Blockly.Extensions.isRegistered(mExtensionName)) {
      Blockly.Extensions.unregister(mExtensionName);
    }
    // ? Register the new/updated extension
    Blockly.Extensions.register(mExtensionName, function () {
      this.data = { CustomID: mBlockID, BlockType: "LOGIC", IsHeadBlock: true };
    });
  }

  function formatColumnsForSQL(columnsList) {
    // ? Map over the columns array and format each column name
    const formattedColumns = columnsList.map(function (column) {
      // ? Trim any leading/trailing whitespace
      const columnName = column.trim();

      // ? Wrap the column name in square brackets if it contains spaces
      if (columnName.includes(" ")) {
        // 16Mar2025 return `[${columnName}]`;
        return `"${columnName}"`; // ? 16Mar2025, DuckDB expects column names with spaces to be enclosed in double quotes
      } else {
        return columnName;
      }
    });

    let sqlStr = ""; //
    for (let i = 0; i < formattedColumns.length; i++) {
      sqlStr += `${formattedColumns[i]}`;
      if (i < formattedColumns.length - 1) {
        sqlStr += ", ";
      }
    }

    return sqlStr;
  }

  function generateSQLCodeForBlock() {
    // ? Generate the JavaScript code for this block
    javascriptGenerator.forBlock[mBlockName] = function (block) {
      let code = "";
      // 21Feb2025 const tblName = `tblHeadBlock_${mBlockID}`;
      const blockID = block.data.CustomID; // 21Feb2025
      const tblName = `tblHeadBlock_${blockID}`; // 21Feb2025

      // ? DISTINCT operator
      const distinctOperator = block.getFieldValue("DISTINCT_OPERATOR");
      if (distinctOperator === "DISTINCT") {
        code = `Create Or Replace Table ${tblName} As SELECT DISTINCT `;
      }
      code = `Create Or Replace Table ${tblName} As SELECT `;

      // ? DATASET and COLUMN
      const datasetName = block.getFieldValue("DATASET");
      const dataset = mDatasetList.find(function (d) {
        return d.Name === datasetName;
      });
      const datasetSelColumnsList = dataset.SelColumnsList.map(function (d) {
        return d.ColumnName;
      });

      const datasetSQLStr = formatColumnsForSQL(datasetSelColumnsList); // 14Aug2024

      /*  // 11Feb2025
      let readDatasetSQL;
      if (dataset.Origin === mDatasetOriginTypes.Remote) {
        // 08Feb2025 readDatasetSQL = `read_parquet('${dataset.Url}')`;
        const readFunctionTypes = {
          CSV: "read_csv_auto",
          JSON: "read_json_auto",
          GEOJSON: "ST_Read",
          PARQUET: "read_parquet"
        };
        const readFunction = readFunctionTypes[dataset.DatasetType.toUpperCase()]; // 08Feb2025
        readDatasetSQL = `${readFunction}('${dataset.Url}')`;
      } else if (dataset.Origin === mDatasetOriginTypes.Block) {
        readDatasetSQL = dataset.TableName;
      } */
      const readDatasetSQL = dataset.TableName; // 11Feb2025

      code = code += ` ${datasetSQLStr} FROM ${readDatasetSQL}`;

      // 22Feb2025 return code;
      const jsonObj = {
        sqlCode: code
      };
      return JSON.stringify(jsonObj) + ";\n";
    };
  }

  function getDatasetNamesList() {
    const datasetOptions = [];
    for (let i = 0; i < mDatasetList.length; i += 1) {
      datasetOptions.push([mDatasetList[i].Name, mDatasetList[i].Name]);
    }

    return datasetOptions;
  }

  // 11Aug2024
  function runBlockJsonInit() {
    const datasetOptions = getDatasetNamesList();
    Blockly.Blocks[mBlockName] = {
      init: function () {
        this.jsonInit({
          type: mBlockName,
          message0: "Find %1 %2",
          args0: [
            {
              type: "field_dropdown",
              name: "DISTINCT_OPERATOR",
              options: [
                ["All", "ALL"],
                ["Unique", "DISTINCT"]
              ]
            },
            {
              type: "field_dropdown",
              name: "DATASET",
              options: datasetOptions
            }
          ],
          // 20May2024 id: Blockly.utils.genUid(),   // 20May2024
          data: { CustomID: mBlockID, BlockType: "LOGIC", IsHeadBlock: true }, // ? I don't like the structure of the UID that Blockly generates
          extensions: [mExtensionName],
          nextStatement: null,
          colour: 200,
          tooltip: "Find the occurrence of...",
          helpUrl: ""
        });
      },
      // 15Sep2024
      updateFieldDropdownList: function (config) {
        mDatasetList = config.DatasetList;
        const datasetOptions = getDatasetNamesList();

        const updateDropdown = (field, options) => {
          const currentValue = field.getValue();
          field.menuGenerator_ = options;

          // Check if the current value exists in the new options
          const valueExists = options.some(
            (option) => option[1] === currentValue
          );

          if (valueExists) {
            // If the current value still exists, keep it
            field.setValue(currentValue);
          } else {
            // If the current value doesn't exist, set to the first option
            field.setValue(options[0][1]);
          }

          field.forceRerender();
        };

        // Update DATASET
        const datasetDDL = this.getField("DATASET");
        updateDropdown(datasetDDL, datasetOptions);
      }
    };
  }

  async function createBlock() {
    runBlockJsonInit();

    addBlockToToolsCategory();
    generateSQLCodeForBlock();
  }

  /*  // 15Sep2024
  publicAPI.update = function (config) {
    mDatasetList = config.DatasetList;
    runBlockJsonInit();

    // ? Re-render the workspace
    Blockly.getMainWorkspace().render();
  }; */

  publicAPI.init = async function (config) {
    mHelperUtil = new HelperUtil();
    mToolsCategory = config.ToolsCategory;
    mDatasetList = config.DatasetList;
    mBlockID = mHelperUtil.generateShortGUID();
    Blockly.setLocale(En);
    registerExtension();
    await createBlock();
  };

  return publicAPI;
}
export default FindBlock;
